public class MainActivity extends Activity {
 JSONObject db; LinearLayout body; String tab="오늘"; final int ink=Color.rgb(26,43,42),accent=Color.rgb(28,112,94);
 JSONArray arr(String k){return db.optJSONArray(k);}
 JSONObject obj(Object... kv){JSONObject o=new JSONObject();try{for(int i=0;i<kv.length;i+=2)o.put((String)kv[i],kv[i+1]);}catch(Exception e){throw new RuntimeException(e);}return o;}
 void put(String k,Object v){try{db.put(k,v);}catch(Exception e){throw new RuntimeException(e);}}
 public void onCreate(Bundle state){super.onCreate(state);try{db=new JSONObject(getSharedPreferences("fit",0).getString("db","{\"version\":1,\"exercises\":[],\"logs\":[],\"plan\":[],\"appointments\":[],\"weekly\":3}"));}catch(Exception e){throw new IllegalStateException("저장 데이터를 읽을 수 없습니다",e);}show();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},7);}
 void save(){getSharedPreferences("fit",0).edit().putString("db",db.toString()).apply();ReminderReceiver.schedule(this);}
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n);}
 TextView text(LinearLayout parent,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setPadding(0,dp(8),0,dp(8));parent.addView(t);return t;}
 android.graphics.drawable.GradientDrawable surface(int color,int radius){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
 void button(LinearLayout p,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);boolean secondary=s.contains("수정")||s.contains("삭제")||s.contains("제외");b.setTextColor(secondary?accent:Color.WHITE);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x22339988),surface(secondary?0xffe8f0eb:accent,16),null));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(52));bp.setMargins(0,dp(6),0,dp(6));p.addView(b,bp);b.setOnClickListener(v->r.run());}
 LinearLayout box(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(16),dp(10),dp(16),dp(12));b.setBackground(surface(Color.WHITE,22));b.setElevation(dp(1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));body.addView(b,lp);return b;}
 EditText field(LinearLayout p,String hint,String val,boolean number){text(p,hint,13);EditText e=new EditText(this);e.setPadding(dp(12),dp(8),dp(12),dp(8));e.setBackground(surface(0xffeef3ef,10));e.setMinHeight(dp(48));e.setHint(hint);e.setText(val);if(number)e.setInputType(8194);p.addView(e);return e;}
 LinearLayout form(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(20),dp(12),dp(20),dp(12));return p;}
 interface Accept{void run()throws Exception;}
 void dialog(String title,LinearLayout f,Accept a){ScrollView s=new ScrollView(this);s.addView(f);AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(s).setNegativeButton("취소",null).setPositiveButton("저장",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{a.run();save();d.dismiss();show();}catch(Exception e){toast("입력값을 확인해 주세요: "+e.getMessage());}}));d.show();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 String date(long time){return new SimpleDateFormat("M월 d일 (E) HH:mm",Locale.KOREA).format(new Date(time));}
 String day(long time){return new SimpleDateFormat("yyyy-MM-dd",Locale.KOREA).format(new Date(time));}
 String today(){return day(System.currentTimeMillis());}
 void show(){
 LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xfff3f5f1);setContentView(root);
 root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(20),i.getSystemWindowInsetTop()+dp(12),dp(20),i.getSystemWindowInsetBottom());return i;});
 TextView brand=text(root,"MY FIT LOG  /  나의 꾸준함",12);brand.setTextColor(accent);brand.setLetterSpacing(.12f);
 TextView title=text(root,tab.equals("오늘")?"오늘도, 한 걸음":tab.equals("운동")?"나의 운동 라이브러리":tab.equals("기록")?"쌓여가는 기록":tab.equals("예약")?"다음 PT 준비":"나에게 맞게",27);title.setTypeface(null,android.graphics.Typeface.BOLD);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,dp(8),0,dp(16));scroll.addView(body);
 LinearLayout nav=new LinearLayout(this);nav.setPadding(0,dp(8),0,dp(8));root.addView(nav);String[] tabs={"오늘","기록","운동","예약","설정"};String[] marks={"◉","▤","＋","▦","⚙"};for(int n=0;n<tabs.length;n++){String dest=tabs[n];TextView t=new TextView(this);t.setText(marks[n]+"\\n"+dest);t.setGravity(Gravity.CENTER);t.setTextSize(13);t.setTextColor(tab.equals(dest)?accent:0xff77817b);t.setBackground(surface(tab.equals(dest)?0xffdcebdc:0xfff3f5f1,16));nav.addView(t,new LinearLayout.LayoutParams(0,dp(58),1));t.setContentDescription(dest+" 탭");t.setOnClickListener(v->{tab=dest;show();});}
 switch(tab){case "오늘":home();break;case "운동":exercises();break;case "기록":logs();break;case "예약":appointments();break;default:settings();}
 }
 void home(){LinearLayout b=box();text(b,"상체 근력 · 자세 익히기",20);text(b,"PT 입문  /  집: 3kg 덤벨 × 2 · 철봉",14);Calendar start=Calendar.getInstance();start.set(Calendar.DAY_OF_WEEK,Calendar.MONDAY);start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);start.set(Calendar.SECOND,0);start.set(Calendar.MILLISECOND,0);if(start.getTimeInMillis()>System.currentTimeMillis())start.add(Calendar.DAY_OF_MONTH,-7);Set<String> days=new HashSet<>();for(int i=0;i<arr("logs").length();i++){JSONObject l=arr("logs").optJSONObject(i);if(l.optLong("time")>=start.getTimeInMillis())days.add(day(l.optLong("time")));}text(b,"이번 주 "+days.size()+" / "+db.optInt("weekly",3)+"일 운동",18);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(db.optInt("weekly",3));progress.setProgress(days.size());progress.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));b.addView(progress,new LinearLayout.LayoutParams(-1,dp(8)));
 JSONObject next=null;for(int i=0;i<arr("appointments").length();i++){JSONObject p=arr("appointments").optJSONObject(i);if(p.optLong("time")>System.currentTimeMillis()&&(next==null||p.optLong("time")<next.optLong("time")))next=p;}text(b,next==null?"다음 PT 예약을 등록해 주세요":"다음 PT · "+date(next.optLong("time")),16);
 button(body,"오늘 루틴 구성",()->new AlertDialog.Builder(this).setTitle("운동 장소").setItems(new String[]{"집","헬스장 개인 운동","PT"},(d,n)->choosePlan(n)).show());
 boolean any=false;for(int i=0;i<arr("plan").length();i++){JSONObject p=arr("plan").optJSONObject(i);if(!today().equals(p.optString("date")))continue;any=true;LinearLayout c=box();text(c,p.optString("name"),21);text(c,p.optString("place")+" · "+p.optString("kg")+"kg · "+p.optString("reps")+"회 × "+p.optString("sets")+"세트",15);text(c,p.optString("note"),15);int completed=0;for(int j=0;j<arr("logs").length();j++){JSONObject l=arr("logs").optJSONObject(j);if(today().equals(day(l.optLong("time")))&&l.optString("id").equals(p.optString("id"))&&l.optString("place").equals(p.optString("place")))completed++;}text(c,"오늘 완료 "+completed+" / "+p.optString("sets")+"세트",16);button(c,"세트 기록하기",()->record(p));final int index=i;button(c,"계획에서 제외",()->{arr("plan").remove(index);save();show();});}if(!any){LinearLayout empty=box();text(empty,"첫 운동을 골라볼까요?",22);text(empty,"이름을 입력할 필요 없이 기본 목록에서 선택하세요. 운동을 추가한 뒤 오늘 할 루틴을 구성할 수 있어요.",15);button(empty,"운동 찾아보기",()->catalog());}
 }
 long lastTime(String id){long t=0;for(int i=0;i<arr("logs").length();i++){JSONObject l=arr("logs").optJSONObject(i);if(id.equals(l.optString("id")))t=Math.max(t,l.optLong("time"));}return t;}
 void choosePlan(int place){JSONArray ex=arr("exercises");ArrayList<JSONObject> eligible=new ArrayList<>();for(int i=0;i<ex.length();i++){JSONObject e=ex.optJSONObject(i);if(place!=0||e.optBoolean("home"))eligible.add(e);}if(eligible.isEmpty()){toast("먼저 해당 장소에서 가능한 운동을 등록해 주세요.");return;}eligible.sort((a,b)->Long.compare(lastTime(a.optString("id")),lastTime(b.optString("id"))));String[] names=new String[eligible.size()];boolean[] selected=new boolean[names.length];for(int i=0;i<names.length;i++){names[i]=eligible.get(i).optString("name");selected[i]=i<3;}new AlertDialog.Builder(this).setTitle("최근에 덜 한 운동 순 · 최대 3개 기본 선택").setMultiChoiceItems(names,selected,(d,n,c)->selected[n]=c).setNegativeButton("취소",null).setPositiveButton("계획 적용",(d,w)->{JSONArray plan=new JSONArray();for(int i=0;i<arr("plan").length();i++){JSONObject p=arr("plan").optJSONObject(i);if(!today().equals(p.optString("date")))plan.put(p);}for(int i=0;i<names.length;i++)if(selected[i]){JSONObject e=eligible.get(i);plan.put(obj("date",today(),"name",e.optString("name"),"id",e.optString("id"),"kg",place==0&&e.optString("equipment").contains("덤벨")?"3":e.optString("kg"),"reps",e.optString("reps"),"sets",e.optString("sets"),"note",e.optString("note"),"place",new String[]{"집","헬스장","PT"}[place]));}put("plan",plan);save();show();}).show();}
 void exercises(){button(body,"＋ 기본 운동에서 고르기",()->catalog());button(body,"목록에 없는 운동 직접 추가",()->editExercise(null));text(body,"내 운동 "+arr("exercises").length()+"개 · 집에서 가능 여부는 직접 설정해요",14);for(int i=0;i<arr("exercises").length();i++){JSONObject e=arr("exercises").optJSONObject(i);LinearLayout b=box();text(b,e.optString("name"),21);text(b,e.optString("equipment")+" · "+(e.optBoolean("home")?"집에서도 가능":"헬스장"),14);text(b,e.optString("note"),16);button(b,"자세 메모 · 목표 수정",()->editExercise(e));}}

 // Catalog entries are choices, never automatically enrolled or marked learned.
 final String[][] basics={
 {"덤벨 컬","팔","덤벨"},{"해머 컬","팔","덤벨"},{"덤벨 킥백","팔","덤벨"},{"케이블 푸시다운","팔","케이블"},
 {"덤벨 숄더 프레스","어깨","덤벨"},{"아놀드 프레스","어깨","덤벨"},{"사이드 레터럴 레이즈","어깨","덤벨"},{"리버스 펙덱 플라이","어깨","머신"},
 {"랫풀다운","등","머신"},{"시티드 케이블 로우","등","케이블"},{"원암 덤벨 로우","등","덤벨"},{"체스트 서포티드 로우","등","머신"},{"페이스 풀","등","케이블"},
 {"체스트 프레스","가슴","머신"},{"펙덱 플라이","가슴","머신"},{"덤벨 벤치 프레스","가슴","덤벨 + 벤치"},{"덤벨 플로어 프레스","가슴","덤벨"},{"푸시업","가슴","맨몸"},
 {"풀업","철봉","철봉"},{"친업","철봉","철봉"},{"스캐풀라 풀업","철봉","철봉"}};
 void catalog(){
 LinearLayout f=form();text(f,"이름을 골라 추가하세요",22);text(f,"등록은 운동 추천이나 수행 가능 판정이 아니에요. 목표와 집에서 가능 여부는 추가 후 설정하세요.",14);
 EditText query=field(f,"운동 이름 · 부위 · 장비 검색","",false);LinearLayout chips=new LinearLayout(this);HorizontalScrollView hs=new HorizontalScrollView(this);hs.addView(chips);f.addView(hs);
 LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);f.addView(results);
 Runnable render=()->{results.removeAllViews();String q=query.getText().toString().trim();int count=0;for(String[] row:basics){if(!(row[0]+" "+row[1]+" "+row[2]).contains(q))continue;count++;boolean exists=false;for(int i=0;i<arr("exercises").length();i++)if(row[0].equals(arr("exercises").optJSONObject(i).optString("name")))exists=true;
 final boolean added=exists;button(results,row[0]+"  ·  "+row[1]+" / "+row[2]+(added?"  ✓":""),()->{if(added){toast("이미 내 운동에 있어요");return;}LinearLayout setup=form();text(setup,row[0],22);text(setup,row[1]+" · "+row[2],15);text(setup,"추가 후 자세 메모와 목표를 수정할 수 있어요. 아래 숫자는 입력 시작값이에요.",14);CheckBox home=new CheckBox(this);home.setText("집에서 혼자 수행할 수 있어요");setup.addView(home);dialog("내 운동에 추가",setup,()->{arr("exercises").put(obj("id",UUID.randomUUID().toString(),"name",row[0],"equipment",row[2],"note","","kg",row[2].equals("덤벨")?"3":"0","reps","10","sets","2","home",home.isChecked()));});});}if(count==0)text(results,"일치하는 운동이 없어요. 내 운동 화면에서 직접 추가할 수 있어요.",15);};
 for(String category:new String[]{"전체","팔","어깨","등","가슴","철봉"}){TextView chip=new TextView(this);chip.setText(category);chip.setTextSize(15);chip.setPadding(dp(14),dp(14),dp(14),dp(14));chip.setTextColor(accent);chips.addView(chip);chip.setOnClickListener(v->query.setText(category.equals("전체")?"":category));}
 query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence t,int st,int c,int a){}public void onTextChanged(CharSequence t,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable t){}});
 render.run();ScrollView sc=new ScrollView(this);sc.addView(f);AlertDialog picker=new AlertDialog.Builder(this).setView(sc).setPositiveButton("완료",(d,w)->{tab="운동";show();}).create();picker.show();picker.getWindow().setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*.88));picker.setOnDismissListener(d->{tab="운동";show();});
 }

 void editExercise(JSONObject old){JSONObject e=old==null?obj():old;LinearLayout f=form();EditText name=field(f,"정확한 운동 이름",e.optString("name"),false),equipment=field(f,"장비 이름",e.optString("equipment","덤벨"),false),note=field(f,"PT 자세 메모 · 주의사항",e.optString("note"),false),kg=field(f,"목표 무게 kg (덤벨은 한 개 기준)",e.optString("kg","3"),true),reps=field(f,"목표 횟수",e.optString("reps","12"),true),sets=field(f,"목표 세트",e.optString("sets","3"),true);CheckBox home=new CheckBox(this);home.setText("집 장비로 혼자 수행할 수 있어요 (덤벨·철봉·맨몸)");home.setChecked(e.optBoolean("home"));f.addView(home);dialog("내 운동",f,()->{if(name.getText().toString().trim().isEmpty())throw new Exception("운동 이름");positive(kg,true);positive(reps,false);positive(sets,false);e.put("id",e.optString("id",UUID.randomUUID().toString()));e.put("name",name.getText().toString().trim());e.put("equipment",equipment.getText());e.put("note",note.getText());e.put("kg",kg.getText());e.put("reps",reps.getText());e.put("sets",sets.getText());e.put("home",home.isChecked());if(old==null)arr("exercises").put(e);});}
 double positive(EditText e,boolean decimal)throws Exception{double n=Double.parseDouble(e.getText().toString());if(!Double.isFinite(n)||n<0||(!decimal&&(n<1||n!=Math.floor(n)))||n>1000)throw new Exception("무게·횟수·세트 범위");return n;}
 void record(JSONObject p){LinearLayout f=form();text(f,p.optString("note"),16);JSONObject last=null;for(int i=arr("logs").length()-1;i>=0;i--){JSONObject l=arr("logs").optJSONObject(i);if(l.optString("id").equals(p.optString("id"))&&l.optString("place").equals(p.optString("place"))){last=l;break;}}if(last!=null)text(f,"지난 기록: "+last.optString("kg")+"kg · "+last.optString("reps")+"회",16);EditText kg=field(f,"무게 kg",last==null?p.optString("kg"):last.optString("kg"),true),reps=field(f,"완료 횟수",last==null?p.optString("reps"):last.optString("reps"),true),memo=field(f,"힘든 정도 · 불편한 부위 · 오늘 피드백","",false);dialog(p.optString("name")+" · 1세트 기록",f,()->{positive(kg,true);positive(reps,false);arr("logs").put(obj("time",System.currentTimeMillis(),"id",p.optString("id"),"name",p.optString("name"),"place",p.optString("place"),"kg",kg.getText().toString(),"reps",reps.getText().toString(),"memo",memo.getText().toString()));});}
 void logs(){if(arr("logs").length()==0)text(body,"완료한 세트가 여기에 쌓여요.",18);for(int i=arr("logs").length()-1;i>=0;i--){JSONObject l=arr("logs").optJSONObject(i);LinearLayout b=box();text(b,l.optString("name")+" · "+l.optString("kg")+"kg × "+l.optString("reps")+"회",19);text(b,date(l.optLong("time"))+" / "+l.optString("place"),14);text(b,l.optString("memo"),15);final int index=i;button(b,"잘못 입력한 세트 삭제",()->new AlertDialog.Builder(this).setMessage("이 세트 기록을 삭제할까요?").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{arr("logs").remove(index);save();show();}).show());}}
 void appointments(){button(body,"+ PT 예약",()->appointment(null));text(body,"알림은 기본 60분 전입니다. 절전 모드에서는 지연될 수 있어요.",14);if(Build.VERSION.SDK_INT>=33&&!getSystemService(NotificationManager.class).areNotificationsEnabled())button(body,"알림 권한 켜기",()->startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName())));for(int i=0;i<arr("appointments").length();i++){JSONObject p=arr("appointments").optJSONObject(i);LinearLayout b=box();text(b,date(p.optLong("time")),20);text(b,p.optString("note")+" · "+p.optInt("minutes",60)+"분 전 알림",15);button(b,"예약 수정",()->appointment(p));final int index=i;button(b,"예약 삭제",()->{AlarmManager am=getSystemService(AlarmManager.class);am.cancel(PendingIntent.getBroadcast(this,p.optInt("id"),new Intent(this,ReminderReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));arr("appointments").remove(index);save();show();});}}
 void appointment(JSONObject old){Calendar c=Calendar.getInstance();if(old!=null)c.setTimeInMillis(old.optLong("time"));new DatePickerDialog(this,(v,y,m,d)->{c.set(y,m,d);new TimePickerDialog(this,(t,h,min)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);LinearLayout f=form();text(f,date(c.getTimeInMillis()),18);EditText note=field(f,"예약 메모",old==null?"":old.optString("note"),false),minutes=field(f,"몇 분 전 알림",old==null?"60":old.optString("minutes"),true);dialog("PT 예약",f,()->{positive(minutes,false);if(c.getTimeInMillis()<=System.currentTimeMillis())throw new Exception("미래 시간을 선택하세요");JSONObject p=old==null?obj("id",(int)(System.currentTimeMillis()&0x7fffffff)):old;p.put("time",c.getTimeInMillis());p.put("note",note.getText().toString());p.put("minutes",Integer.parseInt(minutes.getText().toString()));if(old==null)arr("appointments").put(p);});},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 void settings(){LinearLayout b=box();text(b,"재호 · 1986년생",22);text(b,"상체 근육 키우기 · 자세 개선\n장비: 3kg 덤벨 두 개 · 철봉\n로그인 없이 기기에 저장됩니다.",16);button(body,"주간 운동 목표 변경",()->{LinearLayout f=form();EditText n=field(f,"주당 운동 일수",String.valueOf(db.optInt("weekly",3)),true);dialog("주간 목표",f,()->{double value=positive(n,false);if(value>7)throw new Exception("1~7일");put("weekly",(int)value);});});button(body,"JSON 백업 저장",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"my-fit-log-"+today()+".json"),10));button(body,"백업 복원",()->new AlertDialog.Builder(this).setMessage("복원하면 현재 기록이 백업 내용으로 교체됩니다.").setNegativeButton("취소",null).setPositiveButton("파일 선택",(d,w)->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),11)).show());}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;try{if(request==10){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(db.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}toast("백업 완료");}else if(request==11){JSONObject restored;try(java.io.InputStream in=getContentResolver().openInputStream(data.getData());java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>10000000)throw new Exception("파일이 너무 큽니다");}restored=new JSONObject(out.toString("UTF-8"));}if(restored.optInt("version")!=1)throw new Exception("지원하지 않는 백업");for(String key:new String[]{"exercises","logs","plan","appointments"}){JSONArray a=restored.getJSONArray(key);for(int i=0;i<a.length();i++)a.getJSONObject(i);}for(int i=0;i<arr("appointments").length();i++)getSystemService(AlarmManager.class).cancel(PendingIntent.getBroadcast(this,arr("appointments").getJSONObject(i).getInt("id"),new Intent(this,ReminderReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));db=restored;save();show();toast("복원 완료");}}catch(Exception e){toast("파일 처리 실패: "+e.getMessage());}}
}
